import math

def primos_ate_n(n):
    if n < 2:
        return []

    primos = []
    for numero in range(2, n + 1):
        eh_primo = True
        for divisor in range(2, int(math.sqrt(numero)) + 1):
            if numero % divisor == 0:
                eh_primo = False
                break
        if eh_primo:
            primos.append(numero)
    return primos
